INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('blind-crown', 'Blind Crown — Nightfall', '1.6.0', 'experimental', 'imported', 'not-integrated', '{"id":"blind-crown","title":"Blind Crown — Nightfall","aliases":["Blind Crown","Classic Blind Volley"],"tags":["strategy","simultaneous-turns","archery","arcade","party","bots","mobile","canvas"],"description":"Private-plan medieval archery for 2–10 contestant slots. Nightfall adds armored knights, three diorama arenas, four cameras, readable volleys and paused tactical round reviews. Classic and Precision rules preserved. One local human plus bots; hosted phone multiplayer is not integrated.","players":{"min":2,"max":10},"version":"1.6.0","source":{"status":"imported","paths":["source/index.html","source/original/blind-crown-v1.4.html"],"provenance":"Nightfall v1.6 tactical learning upgrade over exact supplied Refined v1.4, preserved under source/original/. Original Canvas/SVG art and synthesized audio; no added external dependencies/assets. Classic/Precision engine, cameras, art and room client preserved byte-identically. Current standalone SHA-256: 9de02410af76047081cdfff3fe19a0e70641c75a31ae9ded5f7eef0831b0f681. Experimental pinned Three.js remains opt-in/unverified. See tests/sumo-benchmark-verification.json and assets/README.md.","url":null},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-ballistix', 'Royal Ballistix — Beach Siege', '0.14.0', 'experimental', 'imported', 'not-integrated', '{"id":"royal-ballistix","title":"Royal Ballistix — Beach Siege","aliases":["Royal Ballistix","Ballistix","Beach Siege","Royal Ballistix Beach Siege"],"tags":["physics","ball-deflection","survival","arcade","party","bots","mobile","canvas"],"description":"Radial ball-deflection survival for 2–10 contestants. Four physical courts: Beach Siege, wind-driven Gale Harbour, Moonwell vortex and Clockwork Keep deflectors. Silent all-bot title exhibition, 75-second four-court Tour, classic Siege and 60-second Defense Drill; saved grouped rules/style/controls/access preferences, licensed local effects, map-aware bots. Camera/CAM and public seat hooks retained. Phone/network transport is not integrated.","players":{"min":2,"max":10},"version":"0.14.0","source":{"status":"imported","paths":["source/index.html"],"provenance":"Based on edmondsonedits/CALLBACK commit ed09d25b690b36b397516e4d77437e3dd21247c8 (game-modes/royal-ballistix/index.html), with CALLBACK Arcade improvements and the 0.14.0 Worlds revision. Upstream Apache-2.0 and Kenney CC0 asset licenses retained locally. Current standalone SHA-256: 2b33e11ec4662e5fa2452aba9207531faa8e6bba5bef717780e6f4a95a296015. See tests/evidence/worlds-checks.json and docs/quality/worlds-2026-10-12/task-1-report.md for evidence and limitations.","url":"https://github.com/edmondsonedits/CALLBACK/blob/ed09d25b690b36b397516e4d77437e3dd21247c8/game-modes/royal-ballistix/index.html"},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-roller-ruckus', 'Royal Roller Ruckus — Crownway Circuit', '1.5.0', 'experimental', 'imported', 'in-progress', '{"id":"royal-roller-ruckus","title":"Royal Roller Ruckus — Crownway Circuit","aliases":["Royal Roller Ruckus","Roller Ruckus","Crownway Circuit"],"tags":["racing","physics","momentum","arcade","party","bots","mobile","three-js"],"description":"A 2–10 racer momentum-driven cage race on the vertical Crownway with deliberate setup, one-lap practice, checkpoint and corner coaching, lap splits, personal bests, recovery and persistent accessibility preferences.","players":{"min":2,"max":10},"version":"1.5.0","source":{"status":"imported","paths":["source/index.html","source/original/royal_roller_ruckus_v1.4_vertical_crownway.html","source/vendor/three.module.js","source/vendor/three.core.js","source/vendor/LICENSE-three.txt"],"provenance":"Imported from the user-supplied royal_roller_ruckus_v1.4_vertical_crownway.html; original preserved unchanged. Active v1.5.0 adds racing flow, coaching, practice, results and access preferences. Three.js r180 modules and MIT license are byte-identical copies of the existing Royal Sumo vendor distribution; no runtime CDN import.","url":null},"lifecycle":"experimental","multiplayer":{"status":"in-progress","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-scratch-match', 'Royal Scratch Match', '0.6.0', 'experimental', 'imported', 'not-integrated', '{"id":"royal-scratch-match","title":"Royal Scratch Match","aliases":["Scratch Match","Create Scratch Match"],"tags":["rhythm","music","timing","memory","arcade","bots","mobile"],"description":"Standalone Crown & Cadence call-and-response rhythm knockout for 2–10 contestant slots, with rehearsal, musical count-in, timing soundcheck, persistent access settings, touch/keyboard/gamepad chords and seeded set replay. One local player plus bots by default; phone multiplayer is not integrated.","players":{"min":2,"max":10},"version":"0.6.0","source":{"status":"imported","paths":["source/index.html"],"provenance":"Original standalone royal_scratch_match_v0.5_ten_player.html supplied by the user for project/repository use; its exact bytes remain in source/archive. Editable source/index.html upgraded in place to v0.6.0 Crown & Cadence. Original and current SHA-256 provenance plus focused automated-check evidence are recorded in tests/sumo-benchmark-evidence.json. No external runtime assets or dependencies were added.","url":null},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-sumo', 'Royal Sumo — Crownfall', '1.3.0', 'experimental', 'imported', 'in-progress', '{"id":"royal-sumo","title":"Royal Sumo — Crownfall","aliases":["Sumo","Royal Sumo Crownfall","Crownfall Arena"],"tags":["arena","physics","sumo","arcade","party","bots","webgl2","offline","local-multiplayer"],"description":"Royal Sumo: Crownfall v1.3.0: a 2–10 fighter physics brawler with six arenas, Quick Match/Crown Cup, one or two local players and bots. Self-contained WebGL2 build. Phone-room controls and server implemented; public relay deployment pending.","players":{"min":2,"max":10},"version":"1.3.0","controls":{"local":["touch drag to move","hold/release Bash","tap Dash","WASD / Space or J / Shift or K or L","second player: arrows / Enter / Right Shift or period or Numpad0","gamepad stick / A or X / B or Y or RB or RT","Escape or P to pause"],"remoteHooks":["setHumanSlot / setOwner","moveX/moveY or mx/mz","bashDown or bashPressed/bashCharge","dashPressed","optional sequence"]},"source":{"status":"imported","paths":["source/index.html","source/original/royal_sumo_crownfall_v1.3.0.html","source/project/src/app/main.js","source/callback-camera.js","source/online/host.js","source/online/controller.html","source/online/controller.js"],"provenance":"Imported from the user-supplied royal_sumo_crownfall_v1.3.0.zip. Exact standalone HTML retained under source/original/ and complete editable source/tests under source/project/. The active entry adds the existing CALLBACK camera controls and new phone-room controls as separate adapters; imported simulation and modules are unchanged. The former v0.21 CALLBACK entry and its MIT-licensed Three.js dependency are archived together.","url":null},"lifecycle":"experimental","multiplayer":{"status":"in-progress","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-twisted', 'Royal Twisted — Spiral Keep', '0.6.0', 'experimental', 'imported', 'in-progress', '{"id":"royal-twisted","title":"Royal Twisted — Spiral Keep","aliases":["Royal Twisted","Spiral Keep","Twisted System"],"tags":["obstacle","survival","reaction","arcade","party","bots","mobile","three-js"],"description":"A 2–10 contestant survival run around Spiral Keep: jump cyan rods, hold duck under coral rods, recover from setbacks and compete for the crown. Includes seeded replay, jump/duck practice rhythms, full standings and persistent sound/access preferences.","players":{"min":2,"max":10},"version":"0.6.0","source":{"status":"imported","paths":["source/index.html","source/original/royal_twisted_spiral_keep_v0.5_original_camera_knockback.html"],"provenance":"Imported from the user-supplied royal_twisted_spiral_keep_v0.5_original_camera_knockback.html, preserved unchanged beside the active v0.6.0 upgrade. The supplied v0.4 ten-player build remains in source/archive/. Active source bundles unmodified Three.js 0.180.0 locally with MIT license and integrity provenance; benchmark verification and source hashes are recorded in tests/evidence/sumo-benchmark.json.","url":null},"lifecycle":"experimental","multiplayer":{"status":"in-progress","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('space-bash', 'Space Bash — Orbital Breakout', '1.14.0', 'experimental', 'imported', 'not-integrated', '{"id":"space-bash","title":"Space Bash — Orbital Breakout","aliases":["Space Bash","Orbital Breakout"],"tags":["arena","brawler","physics","destruction","arcade","party","bots","mobile","canvas"],"description":"A self-contained 2–10 contestant orbital brawler with aimed cargo throws, kicks, jumps and a destructible deck. Includes flight-school practice, volatile-cargo rules, gamepad aiming and persistent audio/access settings.","players":{"min":2,"max":10},"version":"1.14.0","source":{"status":"imported","paths":["source/index.html","source/original/space_bash_orbital_breakout_v1.13.1_standalone.html"],"provenance":"Imported from the user-supplied space_bash_orbital_breakout_v1.13.1_standalone.html, preserved unchanged under source/original. Active source upgraded to v1.14.0 against Royal Sumo v1.3.0 source, retaining Canvas 2D and no external runtime dependencies. Source hashes and scoped automated evidence are recorded in integration/provenance.json.","url":null},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
